    public static IReadOnlyList<GuiaUso> Buscar(string? texto,string? rol)
    {
        var q=(texto??"").Trim();var compare=CultureInfo.GetCultureInfo("es").CompareInfo;
        return Todas.Where(g=>string.IsNullOrEmpty(rol)||g.Rol==rol).Where(g=>q.Length==0||
            new[]{g.Titulo,g.Resumen,g.Rol,g.Donde}.Concat(g.Pasos).Any(t=>compare.IndexOf(t,q,CompareOptions.IgnoreCase|CompareOptions.IgnoreNonSpace)>=0||compare.IndexOf(Idioma.Texto(t),q,CompareOptions.IgnoreCase|CompareOptions.IgnoreNonSpace)>=0)).ToArray();
    }
